import React from "react";
import Post from "./post-component/Post";
import { Field, reduxForm } from "redux-form";
import {
  requiredField,
  maxLengthCreatore,
} from "../../../../utils/validators/validators";
import { Textarea } from "../../../commons/formControls/formsControl";
import classes from "./MyPosts.module.css";

const maxLength100 = maxLengthCreatore(100);

const MyPosts = React.memo((props) => {
  let postItems = [...props.posts].reverse().map((p) => {
    return (
      <div className={classes.post} key={p.id}>
        <Post message={p.message} like={p.like} />
      </div>
    );
  });

  let addNewPost = (v) => {
    props.onAddPost(v.newPostText);
  };

  return (
    <div className={classes.posts}>
      <h3 className={classes.postsTitle}>Записи</h3>
      <div className="card cardMuted" style={{ marginBottom: 14 }}>
        <AddPostFormRedux onSubmit={addNewPost} />
      </div>
      {postItems.length ? (
        postItems
      ) : (
        <div className="emptyState">
          <strong>Пока нет постов</strong>
          Напиши первую запись выше
        </div>
      )}
    </div>
  );
});

const AddPostForm = (props) => {
  return (
    <form action="" onSubmit={props.handleSubmit}>
      <Field
        component={Textarea}
        name="newPostText"
        placeholder="Что у вас нового?"
        validate={[requiredField, maxLength100]}
      />
      <div className="feedActions" style={{ marginTop: 10 }}>
        <button className="chip" type="submit" style={{ cursor: "pointer", color: "var(--accent-2)", borderColor: "#9ad5cb" }}>
          Опубликовать
        </button>
      </div>
    </form>
  );
};

const AddPostFormRedux = reduxForm({ form: "profileAddPostForm" })(AddPostForm);

export default MyPosts;
